     test.ok(/^PUT/.test(data), 'should be PUT');
   });
  },
  testRequestShouldBeAbleToPOST: function(host, test) {
   rest.post(host).on('complete', function(data) {
     test.ok(/^POST/.test(data), 'should be POST');
   });
